**What this code covers**

- Base A2A Server — FastAPI implementation Every A2A agent runs one of these.
- Base class for all A2A agents.
- JSON-RPC 2.0 dispatcher.
- Handle tasks/send — submit a task.

```python name=a2a_agents/core/server.py
"""
Base A2A Server — FastAPI implementation
Every A2A agent runs one of these.
"""
import json
import asyncio
import uuid
from abc              import ABC, abstractmethod
from typing           import AsyncGenerator
from fastapi          import FastAPI, Request, HTTPException
from fastapi.responses import JSONResponse, StreamingResponse
from fastapi.middleware.cors import CORSMiddleware
from sse_starlette.sse import EventSourceResponse

from core.models import (
    AgentCard, Task, TaskStatus, TaskState,
    TaskSendParams, TaskGetParams, TaskCancelParams,
    A2ARequest, A2AResponse, Message, Artifact,
)

class BaseA2AAgent(ABC):
    """
    Base class for all A2A agents.
    Subclass this and implement `process_task()`.
    """

    def __init__(self, card: AgentCard):
        self.card   = card
        self.tasks: dict[str, Task] = {}
        self.app    = self._build_app()

    def _build_app(self) -> FastAPI:
        app = FastAPI(
            title       = self.card.name,
            description = self.card.description,
            version     = self.card.version,
        )
        app.add_middleware(
            CORSMiddleware,
            allow_origins=["*"],
            allow_methods=["*"],
            allow_headers=["*"],
        )

        # ── Routes ───────────────────────────────
        @app.get("/.well-known/agent.json")
        async def get_agent_card():
            return self.card.model_dump()

        @app.get("/health")
        async def health():
            return {"status": "healthy", "agent": self.card.name}

        @app.post("/a2a")
        async def handle_a2a(request: Request):
            body = await request.json()
            return await self._dispatch(body)

        @app.get("/a2a/stream/{task_id}")
        async def stream_task(task_id: str):
            return EventSourceResponse(
                self._stream_task(task_id)
            )

        return app

    async def _dispatch(self, body: dict) -> JSONResponse:
        """JSON-RPC 2.0 dispatcher."""
        req    = A2ARequest(**body)
        method = req.method

        try:
            if method == "tasks/send":
                result = await self._handle_send(req)
            elif method == "tasks/get":
                result = await self._handle_get(req)
            elif method == "tasks/cancel":
                result = await self._handle_cancel(req)
            elif method == "tasks/sendSubscribe":
                result = await self._handle_send_subscribe(req)
            else:
                return JSONResponse(A2AResponse(
                    id    = req.id,
                    error = {"code": -32601, "message": f"Method not found: {method}"}
                ).model_dump())

            return JSONResponse(A2AResponse(
                id     = req.id,
                result = result,
            ).model_dump())

        except Exception as e:
            return JSONResponse(A2AResponse(
                id    = req.id,
                error = {"code": -32603, "message": str(e)}
            ).model_dump())

    async def _handle_send(self, req: A2ARequest) -> dict:
        """Handle tasks/send — submit a task."""
        params  = TaskSendParams(**req.params)
        task_id = params.id or str(uuid.uuid4())

        # Create task
        task = Task(
            id       = task_id,
            session_id = params.session_id,
            status   = TaskStatus(state=TaskState.SUBMITTED),
            messages = [params.message],
            metadata = params.metadata,
        )
        self.tasks[task_id] = task

        # Process asynchronously
        asyncio.create_task(self._process_and_update(task))

        return task.model_dump()

    async def _handle_get(self, req: A2ARequest) -> dict:
        """Handle tasks/get — get task status."""
        params  = TaskGetParams(**req.params)
        task    = self.tasks.get(params.id)
        if not task:
            raise HTTPException(404, f"Task {params.id} not found")
        return task.model_dump()

    async def _handle_cancel(self, req: A2ARequest) -> dict:
        """Handle tasks/cancel."""
        params  = TaskCancelParams(**req.params)
        task    = self.tasks.get(params.id)
        if task:
            task.status = TaskStatus(state=TaskState.CANCELLED)
        return {"cancelled": True, "task_id": params.id}

    async def _handle_send_subscribe(self, req: A2ARequest) -> dict:
        """Handle tasks/sendSubscribe — returns stream URL."""
        result   = await self._handle_send(req)
        task_id  = result["id"]
        stream_url = f"{self.card.url}/a2a/stream/{task_id}"
        return {**result, "stream_url": stream_url}

    async def _process_and_update(self, task: Task):
        """Runs process_task and updates task state."""
        task.status = TaskStatus(state=TaskState.WORKING)
        try:
            async for update in self.process_task(task):
                if isinstance(update, Artifact):
                    task.artifacts.append(update)
                elif isinstance(update, Message):
                    task.messages.append(update)
                elif isinstance(update, TaskStatus):
                    task.status = update

            # Mark completed
            if task.status.state == TaskState.WORKING:
                task.status = TaskStatus(state=TaskState.COMPLETED)

        except Exception as e:
            task.status = TaskStatus(
                state   = TaskState.FAILED,
                message = Message.agent_text(f"Error: {str(e)}")
            )

    async def _stream_task(self, task_id: str) -> AsyncGenerator:
        """SSE stream for task updates."""
        task      = self.tasks.get(task_id)
        if not task:
            yield {"event": "error", "data": json.dumps({"error": "Task not found"})}
            return

        last_artifact_count = 0

        while task.status.state in [TaskState.SUBMITTED, TaskState.WORKING]:
            await asyncio.sleep(0.1)

            # Stream new artifacts
            if len(task.artifacts) > last_artifact_count:
                for art in task.artifacts[last_artifact_count:]:
                    yield {
                        "event": "artifact",
                        "data":  json.dumps(art.model_dump()),
                    }
                last_artifact_count = len(task.artifacts)

        # Final status
        yield {
            "event": "task_complete",
            "data":  json.dumps(task.model_dump()),
        }

    @abstractmethod
    async def process_task(self, task: Task) -> AsyncGenerator:
        """
        Override this in each agent.
        Yield Artifacts, Messages, or TaskStatus updates.
        """
        ...

    def run(self, host: str = "0.0.0.0", port: int = 8001):
        import uvicorn
        uvicorn.run(self.app, host=host, port=port)
```
